/**
 * Asserts the shape of the Aspire deployment manifest.
 *
 * The manifest is what `aspire deploy` turns into Azure Container Apps, and until deploy slice D3
 * nothing looked at it. What it contained: a front end with **no bindings at all** and
 * `"buildOnly": true` — an image that gets built and never run — behind a generated Dockerfile with
 * no `CMD`. Every test in the repo was green throughout, because none of them is about the artifact.
 *
 * This is deliberately a check on the *manifest* rather than on the built image. The Dockerfile is
 * generated by Aspire from a fixed template, so it does not drift commit to commit; the AppHost
 * configuration that decides which template is used, and what environment the container runs under,
 * drifts every time someone edits it. Building the image in CI would cost several minutes to
 * re-prove what `frontend (lint + build)` already proves, and would still not notice a resource
 * losing its binding.
 *
 * Usage: node scripts/check-deploy-manifest.mjs <path-to-manifest.json>
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";

const path = process.argv[2];
if (!path) {
  console.error("usage: node scripts/check-deploy-manifest.mjs <manifest.json>");
  process.exit(2);
}

const manifest = JSON.parse(readFileSync(path, "utf8"));
const failures = [];

function check(condition, message) {
  if (!condition) failures.push(message);
}

const frontend = manifest.resources?.webfrontend;
check(frontend !== undefined, "no `webfrontend` resource in the manifest");

if (frontend) {
  check(
    frontend.type === "container.v1",
    `webfrontend is "${frontend.type}", expected container.v1 — it has to be an image to deploy`,
  );
  check(
    typeof frontend.build?.dockerfile === "string",
    "webfrontend has no build.dockerfile — nothing would build an image",
  );
  check(
    frontend.build?.buildOnly !== true,
    'webfrontend is buildOnly — the image would be built and never run (this is what `AddJavaScriptApp` produced)',
  );
  check(
    frontend.env?.NODE_ENV === "production",
    `webfrontend NODE_ENV is "${frontend.env?.NODE_ENV}", expected production — development relaxes the CSP in proxy.ts`,
  );

  const external = Object.values(frontend.bindings ?? {}).filter((b) => b.external);
  check(
    external.length > 0,
    "webfrontend has no external binding — the front end would not be reachable",
  );
}

// Postgres must be a managed flexible server, not a container app.
//
// It published as `container.v1` until deploy slice D6 — an always-on container with no
// point-in-time restore, which is the single reason ADR-0011 chose a managed database, and outside
// the free-tier year the costing assumes. The regression is silent in the same way the replica
// counts are: it deploys, it works, and the guarantee the ADR claims is simply absent.
const database = manifest.resources?.postgres;
check(database !== undefined, "no `postgres` resource in the manifest");
check(
  database?.type === "azure.bicep.v0",
  `postgres is "${database?.type}", expected azure.bicep.v0 — a container has no point-in-time restore`,
);

const keycloak = manifest.resources?.keycloak;
check(keycloak !== undefined, "no `keycloak` resource in the manifest");

if (keycloak) {
  // A bind mount names a directory on whoever ran the publisher. It published as
  // `D:/…/FieldKit.AppHost/realms` — the identity provider's entire configuration, sourced from a
  // path no container app has. The realms belong in the image.
  check(
    (keycloak.bindMounts ?? []).length === 0,
    "keycloak has a bind mount — realm import would read a path that does not exist in the cloud",
  );
  check(
    typeof keycloak.build?.dockerfile === "string",
    "keycloak is not built from a Dockerfile — nothing would carry the realms into the image",
  );

  // `start` with no database falls back to the H2 dev-file store, and a restart forgets every user.
  check(
    keycloak.env?.KC_DB === "postgres",
    `keycloak KC_DB is "${keycloak.env?.KC_DB}", expected postgres — the default is an in-image H2 file`,
  );

  // TLS is terminated at the ingress. Without these, Keycloak builds issuer and redirect URLs from
  // its own internal address, and mints tokens the API rejects as coming from an unknown issuer.
  check(
    typeof keycloak.env?.KC_HOSTNAME === "string",
    "keycloak has no KC_HOSTNAME — issuer and redirect URLs would use the container's internal address",
  );
  check(
    keycloak.env?.KC_PROXY_HEADERS === "xforwarded",
    `keycloak KC_PROXY_HEADERS is "${keycloak.env?.KC_PROXY_HEADERS}", expected xforwarded`,
  );

  // The realm files default this to http://localhost:3000. Deployed, that sends every visitor back
  // to their own machine at the end of sign-in.
  check(
    typeof keycloak.env?.FIELDKIT_WEB_ORIGIN === "string",
    "keycloak has no FIELDKIT_WEB_ORIGIN — realm redirect URIs would fall back to localhost:3000",
  );
}

const server = manifest.resources?.server;
check(server !== undefined, "no `server` resource in the manifest");
if (server) {
  const external = Object.values(server.bindings ?? {}).filter((b) => b.external);
  check(external.length > 0, "server has no external binding — the API would not be reachable");
}

/*
 * The scale rules, read out of the generated bicep rather than the manifest.
 *
 * ADR-0011 priced this deployment on three numbers — Keycloak pinned to one replica, the API and
 * the front end at zero — and for four slices they existed only in that document. The bill is
 * decided by what lands in `*-containerapp.module.bicep`, so that is what this reads.
 *
 * It is also the only assertion here that fails *quietly* when it regresses: a wrong `minReplicas`
 * deploys perfectly and shows up six weeks later as a larger invoice.
 */
const EXPECTED_MIN_REPLICAS = { server: 0, webfrontend: 0, keycloak: 1 };

for (const [resource, expected] of Object.entries(EXPECTED_MIN_REPLICAS)) {
  const modulePath = join(dirname(path), `${resource}-containerapp.module.bicep`);

  let bicep;
  try {
    bicep = readFileSync(modulePath, "utf8");
  } catch {
    failures.push(`${resource}: no ${resource}-containerapp.module.bicep — is it published as a container app?`);
    continue;
  }

  const found = bicep.match(/minReplicas:\s*(\d+)/);
  if (!found) {
    failures.push(`${resource}: no minReplicas in its container-app bicep — the platform default decides the bill`);
  } else if (Number(found[1]) !== expected) {
    failures.push(
      `${resource}: minReplicas is ${found[1]}, expected ${expected} ` +
        `(ADR-0011's costing — ${expected === 0 ? "scale to zero when idle" : "warm, because it is on the login path"})`,
    );
  }
}

if (failures.length > 0) {
  for (const failure of failures) console.error(`  ✗ ${failure}`);
  console.error(`\n${failures.length} deploy-manifest check(s) failed.`);
  process.exit(1);
}

console.log(
  "Deploy manifest OK: the front end is a runnable, externally-bound production container, and " +
    "Keycloak carries its realms, has a database, and knows its own address.",
);
